function load$&Identity;$Grid(g) {
  var f = g.get_element().parentForm, voucherCode = f.grid._$voucherCode;
  g.add_onRender(on$&Identity;$Grid$Render);
  g.add_onResponseComplete(on$&Identity;VoucherDetail$ResponseComplete);
  g.add_commandEvent(on$&Identity;VoucherDetail$ExecuteCommand);
  g.$h = [['voucherCode', 'String', voucherCode], ['unitCode', 'String', g._unitCode]];
  if (voucherCode = 'PK1' || voucherCode = 'HD9' || voucherCode = 'PN9') try {f._findButton('Ok').focus();} catch (ex) {}
}
function dispose$&Identity;$Grid(g) {
  try {g.remove_commandEvent(on$&Identity;VoucherDetail$ExecuteCommand} catch (ex) {}
  try {g.remove_onResponseComplete(on$&Identity;VoucherDetail$ResponseComplete);} catch (ex) {}
  try {g.remove_onRender(on$&Identity;$Grid$Render);} catch (ex) {}
}
function on$&Identity;$Grid$Render(sender, eventArgs) {
  var g = eventArgs.grid, f = g.get_element().parentForm;
  var result = f.grid._$result, voucherCode = f.grid._$voucherCode;

  switch (voucherCode) {
    case 'PNA':
    case 'PNG':
    case 'PNE':
    case 'HDF':
    case 'PXC':
      var c0 = g._getColumnOrder('ma_vt');
      for (var i = 0; i < result.length; i++) {
        g._appendRow(null, true);
        var row = g._rowCount, o = g._getItem(row, c0);
        o.row = row;

        var item = result[i][17], site = result[i][21], v = (site == '' ? true : null), t = (site == '' ? 'false' : 'true'), c1 = item ? null : '', c2 = item ? null : true;
        g.setItemGridBehavior(o, [
          ['so_ct', result[i][1], '', true],
          ['ma_vt', item, '', true],
          ['ten_vt%l', result[i][18], '', true],
          ['dvt', result[i][19], '', true],
          ['ten_vt_goc', result[i][51], '', true],
          ['dvt_goc', result[i][52], '', true],
          ['he_so', result[i][20], null, null],
          ['ma_kho', site, '', true],
          ['ma_vi_tri', result[i][22], '', v],
          ['ma_lo', item ? '' : result[i][23], c1, c2],
          ['tk_vt', result[i][29], '', true],
          ['gia_ton', result[i][30], c1, c2],
          ['vi_tri_yn', item ? [result[i][31], t] : result[i][31], c1, c2],
          ['lo_yn', result[i][32], c1, c2],
          ['tao_lo', result[i][33], c1, c2],
          ['nhieu_dvt0', result[i][34], c1, c2],
          ['sua_tk_vt', result[i][35], c1, c2],
          ['so_luong', result[i][24], null, null],
          ['gia_nt0', result[i][25], null, null],
          ['tien_nt0', result[i][26], null, null],
          ['line_nbr', result[i][36], null, null],
          ['thue_suat', result[i][47], null, null],
          ['thue_nt', result[i][62], null, null],
          ['loai_ts', result[i][60], '', true],
          ['tinh_chat', result[i][66], '', true],
          ['ck', result[i][67], null, null],
          ['stt_rec', result[i][68], '', true],
          ['ma_vt_goc', result[i][69], '', true]
        ]);

        if (voucherCode == 'HDF') g.setItemGridBehavior(o, [['tk_tl', result[i][66], null, null], ['kieu_tl', result[i][67], null, null], ['tk_gv', result[i][68], null, null], ['kieu_gv', result[i][69], null, null], ['tk_cpbh', result[i][70], null, null], ['kieu_cpbh', result[i][71], null, null], ['loai_ts', result[i][78], '', null], ['tinh_chat', result[i][65], '', null], ['ck', result[i][79], null, null], ['stt_rec', '', '', null], ['ma_vt_goc', result[i][81], '', null]]);
        if (voucherCode == 'PXC') g.setItemGridBehavior(o, [['ton13', result[i][70], null, null], ['tinh_chat', result[i][71], '', null], ['ck', result[i][72], null, null], ['stt_rec', result[i][73], '', null], ['ma_vt_goc', result[i][74], '', null]]);
        if (item) g.live(o, 'dvt');
        $func.setObjectWhen(g._getItem(row, g._getColumnOrder('dvt')), result[i][34]);
      }
      break;
    case 'PN1':
    case 'PN2':
    case 'PNC':
    case 'HD3':
    case 'PC1':
    case 'BN1':
    case 'PK1':
    case 'HD9':
    case 'PN9':
    case 'PXD':
      var c0 = g._getColumnOrder('dien_giai');
      for (var i = 0; i < result.length; i++) {
        g._appendRow(null, true);
        var row = g._rowCount, o = g._getItem(row, c0);
        o.row = row;

        g.setItemGridBehavior(o, [
          ['so_ct', result[i][1], '', true],
          ['ma_vt', result[i][17], '', true],
          ['ten_vt%l', result[i][18], '', true],
          ['dien_giai', result[i][41], '', true],
          ['dvt', result[i][19], '', true],
          ['ten_vt_goc', result[i][41], '', true],
          ['dvt_goc', result[i][42], '', true],
          ['so_luong', result[i][20], null, null],
          ['gia_nt0', result[i][21], null, null],
          ['tien_nt0', result[i][22], null, null],
          ['line_nbr', result[i][26], null, null],
          ['thue_suat', result[i][23], null, null],
          ['thue_nt', result[i][53], null, null],
          ['loai_ts', result[i][51], '', true],
          ['tinh_chat', result[i][57], '', true],
          ['ck', result[i][58], null, null],
          ['stt_rec', result[i][59], '', true],
          ['t_tien', result[i][7], null, null],
          ['t_thue', result[i][9], null, null],
          ['t_tt', result[i][10], null, null]
        ]);

        if (voucherCode == 'HD3') g.setItemGridBehavior(o, [['loai_ts', result[i][56], '', null], ['tinh_chat', result[i][61], '', null], ['ck', result[i][62], null, null], ['stt_rec', '', '', null]]);
        if (voucherCode == 'PXD') g.setItemGridBehavior(o, [['tinh_chat', result[i][61], '', null], ['ck', result[i][62], null, null], ['stt_rec', result[i][63], '', null]]);
        if (voucherCode == 'BN1') g.setItemGridBehavior(o, [['tinh_chat', result[i][65], '', null], ['ck', result[i][66], null, null], ['stt_rec', result[i][67], '', null]]);
        if (voucherCode == 'PNC') g.setItemGridBehavior(o, [['ma_vt_goc', result[i][60], '', null]]);
      }
      break;
    default:
      break;
  }
  f.getItem('ma_kh').focus();
}
function on$&Identity;VoucherDetail$ResponseComplete(sender, e) {
  var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
  switch (context) {
    case 'Item':
      var v = (result[0].Value == '' ? true : null), t = (result[0].Value == '' ? 'false' : 'true');
      g.setItemGridBehavior(o, [
        ['ma_lo', '', null, null],
        ['ma_kho', result[0].Value, '', null],
        ['ma_vi_tri', result[1].Value, '', v],
        ['dvt', result[2].Value, '', true],
        ['he_so', result[3].Value, null, null],
        ['tk_vt', result[4].Value, '', true],
        ['gia_ton', result[5].Value, null, null],
        ['vi_tri_yn', [result[6].Value, t], null, null],
        ['lo_yn', result[7].Value, null, null],
        ['tao_lo', result[10].Value, null, null],
        ['nhieu_dvt0', result[12].Value, null, null],
        ['sua_tk_vt', result[13].Value, null, null],
        ['tk_tl', result[14].Value, null, null],
        ['kieu_tl', result[15].Value, null, null],
        ['tk_gv', result[16].Value, null, null],
        ['kieu_gv', result[17].Value, null, null],
        ['tk_cpbh', result[18].Value, null, null],
        ['kieu_cpbh', result[19].Value, null, null],
        ['ton13', result[11].Value, null, null]
      ]);
      g.live(o, 'dvt');
      break;
    case 'UOM':
      g.setItemGridBehavior(o, [['he_so', result[0].Value, '', true]]);
      if (g._$voucherCode == 'PXC') g.setItemGridBehavior(o, [['ton13', result[1].Value, '', true]]);
      break;
    default:
      break;
  }
}
function on$&Identity;VoucherDetail$ExecuteCommand(sender, e) {
  var action = e.type.Action, g = sender, f = g.get_element().parentForm, o = e.type.Object, v = f.grid._$voucherCode;
  switch (action) {
    case 'Check':
      if (v == 'PNA' || v == 'PNG' || v == 'PNE' || v == 'HDF'|| v == 'PXC') if (!g.validRowExpression('ma_vt', '([ma_vt] != "")') || !g.validRowExpression('dvt', '([dvt] != "")')) break;
      break;
    case 'BeforeRemoveRow':
      if (!(g._getItemValue(g._activeRow, g._getColumnOrder('tien_nt0')) == 0 && g._getItemValue(g._activeRow, g._getColumnOrder('thue_nt')) == 0)) {
        var msg = g._language == 'v' ? 'Dòng hiện tại có giá trị tiền hoặc thuế khác 0 nên không xóa được.' : 'Cannot delete this record because either the item amount or tax amount is not equal to 0.';
        $message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g._id));

        var formID = g.get_element().parentForm._id;
        var buttonID = formID.substring(0, formID.indexOf('_formExtender')) + '_DialogMessage_dlgOk';

        setTimeout(function() {try {$get(buttonID).focus();} catch (ex) {}}, 10);
        e.type.cancelEvent = true;
        return false;
      }
      f.grid._$result.splice(g._activeRow - 1, 1);
      break;
    default:
      break;
  }
}
function onChange$&Identity;VoucherDetail$Item(o) {
  var g = o.grid, f = g.get_element().parentForm;
  if (f.grid._$voucherCode == 'PXC') {
    g.setItemGridBehavior(o,[['ma_lo', '', '', false]]);
    g.request(o, 'ItemStock', 'Item', ['ma_vt', 'ma_kho', 'ma_vi_tri', ['action', 'Decimal', g.get_element().parentForm._action == 'Edit' ? 1 : 0]], g.$h, true);
    return
  }

  g.request(o, 'Item', 'Item', ['ma_vt', 'ma_kho'], o.grid.$h, true);
}
function onChange$&Identity;VoucherDetail$UOM(o) {
  var g = o.grid, f = g.get_element().parentForm;
  if (f.grid._$voucherCode == 'PXC') {
    g.request(o, 'UOMStock', 'UOM', ['ma_vt', 'ma_kho', 'dvt', 'ma_vi_tri', 'ma_lo', ['action', 'Decimal', g.get_element().parentForm._action == 'Edit' ? 1 : 0]], g.$h, true);
    return
  }

  g.request(o, 'UOM', 'UOM', ['ma_vt', 'ma_kho', 'dvt', 'so_luong'], o.grid.$h, true);
}
